    62→import { WorkspaceSettingsDialog } from "@/components/workspace/workspace-settings-dialog";
    63→import { CreateTaskDialog } from "@/components/workspace/kanban/create-task-dialog";
    64→import type { CreateTaskData } from "@/components/workspace/kanban/create-task-dialog";
    65→import { _useCreateTask } from "@/hooks/use-kanban";
    66→import { useAgents } from "@/hooks/use-workspace-resources";
    67→import { useModels } from "@/hooks/use-models";
    68→import { useGitHubAuth, useGitHubRepository } from "@/hooks/use-github";
    69→import { useDesktopRouting } from "@/hooks/use-desktop-routing";
    70→import { toast } from "@/hooks/use-toast";
    71→import type { AgentInfo, WorkspaceModel } from "@/lib/gateway";
    72→import { invoke } from "@tauri-apps/api/core";
    73→import { PageSection } from "@/pages/apps/components/page-section";
    74→import { useUiStore } from "@/stores";
    75→import type { IconData } from "@/components/ui/icon-picker";
    76→import { normalizeWorkspaceSection } from "@/navigation/navigation-meta";
    77→
    78→interface NavItem {
    79→  titleKey: string;
    80→  href: string;
    81→  icon: React.ElementType;
    82→}
    83→
    84→// Creator section navigation (only visible when authenticated)
    85→const creatorNav: NavItem[] = [
    86→  { titleKey: "creator.publish", href: "/publish", icon: Upload },
    87→  { titleKey: "creator.myPackages", href: "/my-packages", icon: PackageSearch },
    88→  { titleKey: "creator.analytics", href: "/analytics", icon: BarChart3 },
    89→];
    90→
    91→// Workspace navigation items for the active workspace
    92→interface WorkspaceNavItem {
    93→  titleKey: string;
    94→  path: string; // relative path suffix (e.g., "chat", "kanban")
    95→  icon: React.ElementType;
    96→}
    97→
    98→// Base workspace navigation items (always visible)
    99→const baseWorkspaceNavItems: WorkspaceNavItem[] = [
   100→  { titleKey: "workspace.chat", path: "chat", icon: MessageSquare },
   101→  { titleKey: "workspace.kanban", path: "kanban", icon: LayoutDashboard },
   102→  { titleKey: "workspace.scheduledTasks", path: "cron", icon: Clock },
   103→  { titleKey: "workspace.ideas", path: "ideas", icon: Lightbulb },
   104→  { titleKey: "workspace.sections.agents", path: "agent", icon: Bot },
   105→  { titleKey: "workspace.files", path: "files", icon: FolderOpen },
   106→  { titleKey: "workspace.chatMonitor", path: "chat-monitor", icon: Activity },
   107→];
   108→
   109→// GitHub navigation item (shown only when integrated)
   110→const githubNavItem: WorkspaceNavItem = {
   111→  titleKey: "workspace.github.label",
   112→  path: "github",
   113→  icon: Github,
   114→};
   115→
   116→const SIDEBAR_COLLAPSED_KEY = "sidebar-collapsed";
   117→
   118→export function Sidebar() {
   119→  const { t } = useTranslation();
   120→  const { isAuthenticated } = useAuth();
   121→  const { openWorkspaceSection, openWorkspaceHome, openPath, openDashboard } = useDesktopRouting();
   122→
   123→  const {
   124→    workspaces,
   125→    activeWorkspaceId,
   126→    selectWorkspace,
   127→    removeWorkspace,
   128→  } = useLocalWorkspaces();
   129→
   130→  // Add Workspace Modal state
   131→  const [isAddWorkspaceModalOpen, setIsAddWorkspaceModalOpen] = useState(false);
   132→
   133→  // Delete workspace confirmation state
   134→  const [workspaceToDelete, setWorkspaceToDelete] = useState<{ id: string; name: string } | null>(null);
   135→  const [isDeleting, setIsDeleting] = useState(false);
   136→
   137→  // Workspace settings dialog state
   138→  const [workspaceToConfig, setWorkspaceToConfig] = useState<string | null>(null);
   139→
   140→  // Get active workspace
   141→  const activeWorkspace = workspaces.find(ws => ws.id === activeWorkspaceId);
   142→
   143→  // Load collapsed state from localStorage
   144→  const [collapsed, setCollapsed] = useState(() => {
   145→    const saved = localStorage.getItem(SIDEBAR_COLLAPSED_KEY);
   146→    return saved === "true";
   147→  });
   148→
   149→  // Persist collapsed state to localStorage
   150→  useEffect(() => {
   151→    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, String(collapsed));
   152→  }, [collapsed]);
   153→
   154→  const toggleCollapsed = () => setCollapsed((prev) => !prev);
   155→
   156→  // Create Task Dialog state (from global UI store for keyboard shortcut support)
   157→  const { isCreateTaskDialogOpen: isCreateTaskOpen, setCreateTaskDialogOpen: setIsCreateTaskOpen, openChatPopup } = useUiStore();
   158→  const createTaskMutation = _useCreateTask();
   159→
   160→  // Load agents and models for task creation
   161→  const { agents, loading: isLoadingAgents } = useAgents({ workspacePath: activeWorkspace?.path });
   162→  const { models, loading: isLoadingModels } = useModels();
   163→
   164→  // Check GitHub integration status
   165→  const githubAuth = useGitHubAuth(activeWorkspace?.path ?? null);
   166→  const githubRepo = useGitHubRepository(activeWorkspace?.path ?? null);
   167→  const isGitHubIntegrated = !!(githubAuth.status?.authenticated && githubRepo.repository);
   168→
   169→  // Build workspace nav items based on GitHub integration status
   170→  const workspaceNavItems = useMemo(() => {
   171→    if (isGitHubIntegrated) {
   172→      // Insert GitHub after agents, before files
   173→      const items = [...baseWorkspaceNavItems];
   174→      const filesIndex = items.findIndex(item => item.path === "files");
   175→      items.splice(filesIndex, 0, githubNavItem);
   176→      return items;
   177→    }
   178→    return baseWorkspaceNavItems;
   179→  }, [isGitHubIntegrated]);
   180→
   181→  const handleAddWorkspace = () => {
   182→    setIsAddWorkspaceModalOpen(true);
   183→  };
   184→
   185→  const handleSelectWorkspace = (workspaceId: string) => {
   186→    selectWorkspace(workspaceId);
   187→    openWorkspaceSection(workspaceId, "chat");
   188→  };
   189→
   190→  // Handle workspace nav item click - updates current tab
   191→  const handleWorkspaceNavClick = useCallback(
   192→    (workspaceId: string, viewPath: string, _viewName: string, _icon: IconData) => {
   193→      openWorkspaceSection(workspaceId, normalizeWorkspaceSection(viewPath));
   194→    },
   195→    [openWorkspaceSection]
   196→  );
   197→
   198→  // Handle global nav item click - updates current tab
   199→  const handleGlobalNavClick = useCallback(
   200→    (href: string, name: string, icon: IconData) => {
   201→      openPath(href, {
   202→        title: name,
   203→        icon,
   204→        descriptorId: href.startsWith("/settings") ? "settings" : "workspace",
   205→      });
   206→    },
   207→    [openPath]
   208→  );
   209→
   210→  const handleConfigureWorkspace = (workspaceId: string) => {
   211→    setWorkspaceToConfig(workspaceId);
   212→  };
   213→
   214→  const handleOpenInNewWindow = async (workspaceId: string) => {
   215→    try {
   216→      await invoke("open_workspace_in_new_window", { workspaceId });
   217→    } catch (error) {
   218→      console.error("Failed to open workspace in new window:", error);
   219→      toast.error(t("common.error"));
   220→    }
   221→  };
   222→
   223→  const handleDeleteWorkspace = async () => {
   224→    if (!workspaceToDelete) return;
   225→
   226→    setIsDeleting(true);
   227→    try {
   228→      await removeWorkspace(workspaceToDelete.id);
   229→      toast.success(t("workspace.deleteSuccess"));
   230→      // If deleting active workspace, navigate to home
   231→      if (workspaceToDelete.id === activeWorkspaceId) {
   232→        openDashboard();
   233→      }
   234→    } catch (error) {
   235→      console.error("Failed to delete workspace:", error);
   236→      toast.error(t("workspace.deleteFailed"));
   237→    } finally {
   238→      setIsDeleting(false);
   239→      setWorkspaceToDelete(null);
   240→    }
   241→  };
   242→
   243→  // Handle create task submission
   244→  const handleCreateTask = async (data: CreateTaskData) => {
   245→    if (!activeWorkspace) {
   246→      toast.error(t("sidebar.noWorkspaceSelected"));
   247→      return;
   248→    }
   249→
   250→    try {
   251→      await createTaskMutation.mutateAsync({
   252→        title: data.title,
   253→        description: data.description,
   254→        workspace_path: activeWorkspace.path,
   255→        agent_id: data.agentId,       // will be mapped to 'agent'
   256→        model_id: data.modelId,       // will be mapped to 'model'
   257→        auto_start: data.autoStart,   // will be mapped to 'start'
   258→        worktree: data.worktree,
   259→      });
   260→      toast.success(t("sidebar.taskCreated"));
   261→      // Navigate to kanban board to see the new task
   262→      if (activeWorkspaceId) {
   263→        openWorkspaceSection(activeWorkspaceId, "kanban");
   264→      }
   265→    } catch (error) {
   266→      console.error("Failed to create task:", error);
   267→      toast.error(t("sidebar.taskCreateFailed"));
   268→    }
   269→  };
   270→
   271→  return (
   272→    <TooltipProvider delayDuration={0}>
   273→      <aside
   274→        className={cn(
   275→          "flex h-full flex-col border-r border-sidebar-border bg-sidebar transition-all duration-300",
   276→          collapsed ? "w-16" : "w-56"
   277→        )}
   278→      >
   279→        {/* Workspace Selector & Collapse Toggle */}
   280→        <div className={cn(
   281→          "flex h-14 items-center border-b border-sidebar-border",
   282→          collapsed ? "justify-center px-2" : "justify-between px-2"
   283→        )}>
   284→          {collapsed ? (
   285→            // Collapsed: clickable workspace icon to expand
   286→            <Tooltip>
   287→              <TooltipTrigger asChild>
   288→                <button
   289→                  type="button"
   290→                  onClick={toggleCollapsed}
   291→                  className="transition-transform duration-200 hover:scale-105 p-2"
   292→                >
   293→                  <FolderOpen className="h-5 w-5 text-primary" />
   294→                </button>
   295→              </TooltipTrigger>
   296→              <TooltipContent side="right">
   297→                {activeWorkspace?.type === "global"
   298→                  ? t("workspace.global")
   299→                  : (activeWorkspace?.name || t("sidebar.expand"))}
   300→              </TooltipContent>
   301→            </Tooltip>
   302→          ) : (
   303→            // Expanded: show workspace dropdown and collapse button
   304→            <>
   305→              <DropdownMenu>
   306→                <DropdownMenuTrigger asChild>
   307→                  <Button
   308→                    variant="ghost"
   309→                    className="h-9 flex-1 justify-between px-2 text-sidebar-foreground hover:bg-sidebar-accent mr-1"
   310→                  >
   311→                    <span className="flex items-center gap-2 truncate">
   312→                      <FolderOpen className="h-4 w-4 shrink-0 text-primary" />
   313→                      <span className="truncate text-sm font-medium">
   314→                        {activeWorkspace?.type === "global"
   315→                          ? t("workspace.global")
   316→                          : (activeWorkspace?.name || t("workspace.noWorkspaces"))}
   317→                      </span>
   318→                    </span>
   319→                    <ChevronDown className="h-4 w-4 shrink-0 opacity-50" />
   320→                  </Button>
   321→                </DropdownMenuTrigger>
   322→                <DropdownMenuContent align="start" className="w-56">
   323→                  {workspaces.map((ws) => (
   324→                    <DropdownMenuSub key={ws.id}>
   325→                      <DropdownMenuSubTrigger
   326→                        className="flex items-center justify-between"
   327→                        onClick={(e) => {
   328→                          // Only switch workspace on direct click, not on hover
   329→                          if (e.detail > 0) {
   330→                            handleSelectWorkspace(ws.id);
   331→                          }
   332→                        }}
   333→                      >
   334→                        <span className="flex items-center gap-2 truncate flex-1">
   335→                          <span className="truncate">
   336→                            {ws.type === "global" ? t("workspace.global") : ws.name}
   337→                          </span>
   338→                          {ws.id === activeWorkspaceId && (
   339→                            <Check className="h-3 w-3 text-primary shrink-0" />
   340→                          )}
   341→                        </span>
   342→                      </DropdownMenuSubTrigger>
   343→                      <DropdownMenuSubContent className="w-48">
   344→                        <DropdownMenuItem
   345→                          onClick={() => handleConfigureWorkspace(ws.id)}
   346→                        >
   347→                          <Settings className="h-4 w-4 mr-2" />
   348→                          {t("workspace.configure")}
   349→                        </DropdownMenuItem>
   350→                        <DropdownMenuItem
   351→                          onClick={() => handleOpenInNewWindow(ws.id)}
   352→                        >
   353→                          <ExternalLink className="h-4 w-4 mr-2" />
   354→                          {t("workspace.openInNewWindow")}
   355→                        </DropdownMenuItem>
   356→                        {ws.type !== "global" && (
   357→                          <DropdownMenuItem
   358→                            onClick={() => setWorkspaceToDelete({ id: ws.id, name: ws.name })}
   359→                            className="text-destructive focus:text-destructive"
   360→                          >
   361→                            <Trash2 className="h-4 w-4 mr-2" />
   362→                            {t("workspace.delete")}
   363→                          </DropdownMenuItem>
   364→                        )}
   365→                      </DropdownMenuSubContent>
   366→                    </DropdownMenuSub>
   367→                  ))}
   368→                  {workspaces.length > 0 && <DropdownMenuSeparator />}
   369→                  <DropdownMenuItem
   370→                    onClick={handleAddWorkspace}
   371→                    className="text-primary"
   372→                  >
   373→                    <Plus className="h-4 w-4 mr-2" />
   374→                    {t("workspace.addWorkspace")}
   375→                  </DropdownMenuItem>
   376→                </DropdownMenuContent>
   377→              </DropdownMenu>
   378→              <Tooltip>
   379→                <TooltipTrigger asChild>
   380→                  <Button
   381→                    variant="ghost"
   382→                    size="icon"
   383→                    className="h-8 w-8 shrink-0 text-sidebar-foreground/70 hover:text-sidebar-foreground"
   384→                    onClick={toggleCollapsed}
   385→                  >
   386→                    <PanelLeftClose className="h-4 w-4" />
   387→                  </Button>
   388→                </TooltipTrigger>
   389→                <TooltipContent side="right">
   390→                  {t("sidebar.collapse")}
   391→                </TooltipContent>
   392→              </Tooltip>
   393→            </>
   394→          )}
   395→        </div>
   396→
   397→        {/* Main Navigation with Sections */}
   398→        <ScrollArea className="flex-1 pt-2 px-2">
   399→          {collapsed ? (
   400→            // Collapsed: all items use SidebarIconButton with unified centering
   401→            <div className="flex flex-col gap-1">
   402→              {/* Pages Section - Before Workspace navigation */}
   403→              {activeWorkspaceId && activeWorkspace && (
   404→                <>
   405→                  <PageSection
   406→                    workspaceId={activeWorkspaceId}
   407→                    workspacePath={activeWorkspace.path}
   408→                    collapsed={collapsed}
   409→                  />
   410→                  <div className="grid place-items-center w-full py-2">
   411→                    <Separator className="w-10 bg-sidebar-border" />
   412→                  </div>
   413→                </>
   414→              )}
   415→
   416→              {/* Workspace Pages Section (only when workspace is selected) */}
   417→              {activeWorkspaceId && (
   418→                <>
   419→                  {workspaceNavItems.map((item) => (
   420→                    <WorkspaceNavItemComponent
   421→                      key={item.path}
   422→                      item={item}
   423→                      workspaceId={activeWorkspaceId}
   424→                      collapsed={collapsed}
   425→                      onNavigate={handleWorkspaceNavClick}
   426→                    />
   427→                  ))}
   428→                </>
   429→              )}
   430→
   431→              {/* Creator Section (only when authenticated) */}
   432→              {isAuthenticated && (
   433→                <>
   434→                  <div className="grid place-items-center w-full py-2">
   435→                    <Separator className="w-10 bg-sidebar-border" />
   436→                  </div>
   437→                  {creatorNav.map((item) => (
   438→                    <NavItemComponent key={item.href} item={item} collapsed={collapsed} onNavigate={handleGlobalNavClick} />
   439→                  ))}
   440→                </>
   441→              )}
   442→            </div>
   443→          ) : (
   444→            // Expanded: full layout with sections
   445→            <div className="space-y-4">
   446→              {/* Pages Section - Before Workspace navigation */}
   447→              {activeWorkspaceId && activeWorkspace && (
   448→                <PageSection
   449→                  workspaceId={activeWorkspaceId}
   450→                  workspacePath={activeWorkspace.path}
   451→                  collapsed={collapsed}
   452→                />
   453→              )}
   454→
   455→              {/* Workspace Pages Section (only when workspace is selected) */}
   456→              {activeWorkspaceId && (
   457→                <SidebarSection
   458→                  title={t("sidebar.workspacePages")}
   459→                  collapsible
   460→                  defaultOpen
   461→                  headerAction={
   462→                    <div className="flex items-center gap-0.5">
   463→                      <Tooltip>
   464→                        <TooltipTrigger asChild>
   465→                          <Button
   466→                            variant="ghost"
   467→                            size="icon"
   468→                            className="h-5 w-5 text-sidebar-foreground/50 hover:text-sidebar-foreground"
   469→                            onClick={() => {
   470→                              handleConfigureWorkspace(activeWorkspaceId);
   471→                            }}
   472→                          >
   473→                            <Settings className="h-3.5 w-3.5" />
   474→                          </Button>
   475→                        </TooltipTrigger>
   476→                        <TooltipContent side="right">
   477→                          {t("workspace.configure")}
   478→                        </TooltipContent>
   479→                      </Tooltip>
   480→                      <Tooltip>
   481→                        <TooltipTrigger asChild>
   482→                          <Button
   483→                            variant="ghost"
   484→                            size="icon"
   485→                            className="h-5 w-5 text-sidebar-foreground/50 hover:text-sidebar-foreground"
   486→                            onClick={() => {
   487→                              openWorkspaceHome(activeWorkspaceId);
   488→                            }}
   489→                          >
   490→                            <Home className="h-3.5 w-3.5" />
   491→                          </Button>
   492→                        </TooltipTrigger>
   493→                        <TooltipContent side="right">
   494→                          {t("sidebar.workspaceHome")}
   495→                        </TooltipContent>
   496→                      </Tooltip>
   497→                    </div>
   498→                  }
   499→                >
   500→                  <nav className="flex flex-col gap-1">
   501→                    {workspaceNavItems.map((item) => (
   502→                      <WorkspaceNavItemComponent
   503→                        key={item.path}
   504→                        item={item}
   505→                        workspaceId={activeWorkspaceId}
   506→                        collapsed={collapsed}
   507→                        onNavigate={handleWorkspaceNavClick}
   508→                      />
   509→                    ))}
   510→                  </nav>
   511→                </SidebarSection>
   512→              )}
   513→
   514→              {/* Creator Section (only when authenticated) */}
   515→              {isAuthenticated && (
   516→                <SidebarSection
   517→                  title={t("creator.title")}
   518→                  collapsible
   519→                  defaultOpen
   520→                >
   521→                  <nav className="flex flex-col gap-1">
