    46→/**
    47→ * Extract slug from page path
    48→ * Format: pages/<slug>/SKILL.md -> <slug>
    49→ * Slug can be nested: pages/parent/child/SKILL.md -> parent/child
    50→ */
    51→function extractSlugFromPath(pagePath: string | null): string | null {
    52→  if (!pagePath) return null;
    53→
    54→  // Match pattern: pages/<slug>/SKILL.md (slug can contain slashes for nested pages)
    55→  const match = pagePath.match(/^pages\/(.+)\/SKILL\.md$/);
    56→  if (match) {
    57→    return match[1];
    58→  }
    59→
    60→  // Fallback: try to extract from other patterns
    61→  // pages/<slug> -> <slug>
    62→  if (pagePath.startsWith("pages/")) {
    63→    const slug = pagePath.slice(6); // Remove "pages/" prefix
    64→    // Remove trailing /SKILL.md if present
    65→    return slug.replace(/\/SKILL\.md$/, "");
    66→  }
    67→
    68→  return null;
    69→}
